<#
  Fix-RiderRealtimeResync.ps1
  Compatible with Windows PowerShell 5.1 (no PS7-only syntax used).

  What this fixes:

  RIDERS HAVING TO REFRESH TO SEE NEW ORDERS / ACCEPTED BIDS
  Root cause: a phone's browser tab drops its Supabase realtime WebSocket
  the moment the screen locks or the app is backgrounded - completely
  normal for a rider mid-ride. Supabase's realtime does NOT replay events
  that happened while disconnected, so a bid that got accepted, or a new
  job that came in, while the screen was off just sat there invisible
  until the rider happened to manually refresh.

  Also found and fixed along the way, in src\app\rider\(main)\active-job\page.jsx:
    - The realtime order-update channel had no filter at all (listening to
      every UPDATE on the entire orders table, system-wide) and was torn
      down and recreated from scratch on every single order update.
    - Re-syncing by re-querying "status in (matched, picked_up,
      in_transit)" would have gone silently stale if an order was
      cancelled by someone else while the rider was en route (falls
      outside that status list). Fixed by re-fetching the known order by
      its own id once it's been found the first time, so any status
      change - including a cancellation - is reflected honestly.

  Now both src\app\rider\(main)\dashboard\page.jsx (job feed + bid status)
  and active-job\page.jsx (the current order) explicitly re-sync the
  instant the tab/phone regains visibility, focus, or a network
  connection - not just relying on the realtime channel alone.

  Writes full file content (base64-encoded, written as raw bytes - no
  PowerShell string-escaping of JS/JSX, no BOM-injection risk). Backs up
  every existing file it touches to .fix-backup-rider-resync\ first.

  Run from the ROOT of your local repo clone:
      powershell -ExecutionPolicy Bypass -File .\Fix-RiderRealtimeResync.ps1
#>

$ErrorActionPreference = "Stop"
$root = Get-Location
$backupDir = Join-Path $root ".fix-backup-rider-resync"
if (-not (Test-Path -LiteralPath $backupDir)) { New-Item -ItemType Directory -Path $backupDir | Out-Null }

if (-not (Test-Path -LiteralPath (Join-Path $root "src\app"))) {
    Write-Host "ERROR: src\app not found. Run this script from the repo root." -ForegroundColor Red
    exit 1
}

function Get-FullPath($rel) { return Join-Path $root $rel }

function Backup-Path($full) {
    if (Test-Path -LiteralPath $full) {
        $rel = $full.Substring($root.Path.Length).TrimStart('\','/')
        $dest = Join-Path $backupDir $rel
        $destParent = Split-Path $dest -Parent
        if (-not (Test-Path -LiteralPath $destParent)) { New-Item -ItemType Directory -Path $destParent -Force | Out-Null }
        Copy-Item -LiteralPath $full -Destination $dest -Force
    }
}

function Write-FileFromBase64($relPath, $b64) {
    $full = Get-FullPath $relPath
    $targetParent = Split-Path $full -Parent
    if (-not (Test-Path -LiteralPath $targetParent)) { New-Item -ItemType Directory -Path $targetParent -Force | Out-Null }
    Backup-Path $full
    $bytes = [Convert]::FromBase64String($b64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
}

Write-Host "`nApplying rider realtime resync fixes:" -ForegroundColor Cyan

$b64_DASHBOARD = ""
Write-FileFromBase64 "src\app\rider\(main)\dashboard\page.jsx" $b64_DASHBOARD

$b64_ACTIVEJOB = ""
Write-FileFromBase64 "src\app\rider\(main)\active-job\page.jsx" $b64_ACTIVEJOB

Write-Host "`nDone. Backups saved under .fix-backup-rider-resync\" -ForegroundColor Cyan
Write-Host "Next: npm run build (or your usual dev command), then redeploy to Vercel." -ForegroundColor Cyan
